insert into audit.data_sources (source_id, institution, dataset_name, source_url, source_table, publication_date, reporting_start_date, reporting_end_date, frequency, file_type, downloaded_at, source_hash, methodology_notes, is_active) values
  ('BQK_RAPORT_MUJOR', 'BQK', 'Raporti Mujor i Sistemit të Pagesave', 'https://bqk-kos.org/statistikat/?lang=en', 'Terminalet për pagesa; Trans. sipas terminaleve; Kartelat bankare; Pagesat sipas instrumenteve; Llogaritë e klientëve', NULL, '2025-01-01', NULL, 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', NULL, 'Parsed from the official monthly workbook. Terminal counts and POS transaction counts come from the same publication, so productivity ratios share a universe. Series begins January 2025 and is NOT continuous with the annual report series.', TRUE),
  ('BQK_T15', 'BQK', 'Table 15 — Payment System', 'https://bqk-kos.org/repository/docs/time_series/', '15_Payment_System', NULL, '2007-03-01', NULL, 'monthly', 'XLS', '2026-09-26T08:56:15.115353+00:00', NULL, 'Long-run payment system series. Counts published in thousands and scaled on load. No terminal count exists on this basis, so productivity is not computed for it.', TRUE),
  ('BQK_CARDS_ANNUAL', 'BQK', 'Use of Bank Cards in Kosovo (September 2025 edition)', 'https://bqk-kos.org/repository/docs/SistemiIPagesave/Use%20of%20bank%20cards%20in%20Kosovo.pdf?lang=en', 'Table 2; Figures 2, 4, 26, 27', '2025-09-01', '2024-01-01', '2024-12-31', 'annual', 'PDF', '2026-09-26T08:56:15.115353+00:00', NULL, 'City distribution read from charts inside the PDF, not from a published table. Figures 26 and 27 combine ATM AND POS transactions and are labelled as such.', TRUE),
  ('ATK_QARKULLIMI_2019', 'ATK', 'Open Data — Qarkullimi 2019', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2019-01-01', '2019-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '090f1a538386c6682edcff4fa532f7fe', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2020', 'ATK', 'Open Data — Qarkullimi 2020', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2020-01-01', '2020-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '9b6e1fceb18c542629f75c240b12a877', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2021', 'ATK', 'Open Data — Qarkullimi 2021', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2021-01-01', '2021-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '7540eb0547dca486439c7e7c83aa2762', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2022', 'ATK', 'Open Data — Qarkullimi 2022', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2022-01-01', '2022-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '00861beb6bcc18124c34c2faf6cb547a', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2023', 'ATK', 'Open Data — Qarkullimi 2023', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2023-01-01', '2023-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', 'b6e6257285f2cd4b93bdfc718b5f40c4', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2024', 'ATK', 'Open Data — Qarkullimi 2024', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2024-01-01', '2024-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '92b32e4b365fdaab7e65c125c7877b87', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE),
  ('ATK_QARKULLIMI_2025', 'ATK', 'Open Data — Qarkullimi 2025', 'https://www.atk-ks.org/en/open-data/', 'OD_QarkDataSet', NULL, '2025-01-01', '2025-12-31', 'monthly', 'XLSX', '2026-09-26T08:56:15.115353+00:00', '1be905c4aeac05520469d937bcb34839', 'Aggregated turnover and taxpayer counts by month, municipality, sector and legal form. No taxpayer-level record is present or used.', TRUE);
