insert into core.dim_metric_definition (metric_key, metric_name, official_name, institution, universe, cards_coverage, terminal_coverage, geographic_coverage, count_or_value, stock_or_flow, unit, is_default, methodology, limitations, definition_id) values
  ('pos_rm_allcards', 'POS Transactions — All Cards at Kosovo POS', 'Transaksionet sipas terminaleve — pagesa me kartelë në POS', 'BQK', 'All card payments acquired at POS terminals in Kosovo', 'All cards, domestic and foreign', 'All POS terminals in Kosovo', 'Kosovo, national only', 'both', 'flow', 'count / EUR', TRUE, 'Raport Mujor, sheet ''Trans. sipas terminaleve''. Paired with the POS terminal count from sheet ''Terminalet për pagesa'' in the same publication, so numerator and denominator share a universe.', 'Begins January 2025. Runs about 15% above the Table 15 domestic-plus-foreign series in every overlapping month.', 1),
  ('pos_t15_domestic', 'POS Transactions — Domestic Cards Only', 'Table 15, POS — domestic', 'BQK', 'Cards issued in Kosovo, used at Kosovo POS', 'Kosovo-issued cards only; excludes all foreign cards', 'POS terminals in Kosovo', 'Kosovo, national only', 'both', 'flow', 'count / EUR', FALSE, 'Table 15 of the BQK payment system time series. Counts are published in thousands and are scaled here.', 'Counts start January 2018; values start March 2007. No compatible terminal count exists before 2025, so productivity cannot be computed for the earlier years.', 2),
  ('pos_t15_allcards', 'POS Transactions — Domestic plus Foreign Cards', 'Table 15, POS domestic + POS foreign cards in Kosovo', 'BQK', 'All cards at Kosovo POS, per Table 15', 'Kosovo-issued plus foreign-issued cards used in Kosovo', 'POS terminals in Kosovo', 'Kosovo, national only', 'both', 'flow', 'count / EUR', FALSE, 'Sum of two Table 15 indicators.', 'Foreign-card detail starts January 2018. Still about 15% below the Raport Mujor series; the gap is definitional and stable.', 3),
  ('pos_terminals_annual', 'POS Terminals — Annual Report', 'Use of Bank Cards in Kosovo, Table 2', 'BQK', 'POS terminals at year end, annual publication', 'n/a', 'POS plus EFTPOS', 'Kosovo, plus 7 named cities as shares', 'stock', 'stock', 'terminals', FALSE, 'Annual PDF report.', 'NOT continuous with the monthly series: 20,913 at end-2024 against 25,166 in January 2025. Different universes. Never splice.', 4);
